function ic(name,size=20,extra=''){return `<svg class="icon ${extra}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.sparkle}</svg>`}
const $ = sel => document.querySelector(sel);
const money = n => '$'+Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:Number(n)%1?2:0});
const escapeHtml = val => String(val??'').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const asset = name => `assets/${String(name).replace(/[^a-z0-9-]/g,'')}.svg`;
function readStore(key,fallback){try{const raw=localStorage.getItem('forma_'+key);return raw===null?fallback:JSON.parse(raw)}catch{return fallback}}
function saveStore(key,value){try{localStorage.setItem('forma_'+key,JSON.stringify(value))}catch{}}
const state={
 cart:readStore('cart',[]),wishlist:readStore('wishlist',[]),compare:readStore('compare',[]),orders:readStore('orders',[]),
 productOverrides:readStore('products',{}),deletedProducts:readStore('deleted',[]),newsletter:readStore('newsletter',[]),
 coupon:readStore('coupon',''),drawer:null,quickView:null,mobileMenu:false,adminView:'overview',editProductId:null,
 shop:{category:'All',query:'',sort:'featured',price:650,onlySale:false,page:1,grid:3},
 adminAuthorized:sessionStorage.getItem('forma_admin')==='yes',
 checkoutDone:null,selectedVariant:null
};
function products(){return [...BASE_PRODUCTS.map(p=>({...p,...(state.productOverrides[p.id]||{})})),...Object.values(state.productOverrides).filter(p=>Number(p.id)>100)].filter(p=>!state.deletedProducts.includes(Number(p.id)))}
function getProduct(id){return products().find(p=>p.id===Number(id))}
function cartCount(){return state.cart.reduce((s,i)=>s+i.quantity,0)}
function cartSubtotal(){return state.cart.reduce((s,i)=>s+(getProduct(i.id)?.price||0)*i.quantity,0)}
function discount(){return state.coupon==='FORM10'?Math.round(cartSubtotal()*.1*100)/100:0}
function cartShipping(){return cartSubtotal()-discount()>=150||cartSubtotal()===0?0:12}
function cartTotal(){return Math.max(0,cartSubtotal()-discount())+cartShipping()}
function persist(){['cart','wishlist','compare','orders','products','deleted','newsletter','coupon'].forEach(k=>saveStore(k,k==='products'?state.productOverrides:k==='deleted'?state.deletedProducts:state[k]))}
function iconButton(icon,label,attr=''){return `<button class="icon-button" aria-label="${label}" title="${label}" ${attr}>${ic(icon,21)}</button>`}
function stars(rating,showNumber=true){return `<span class="stars"><span class="star-gold">★</span>${showNumber?`<b>${Number(rating||4.8).toFixed(1)}</b>`:''}</span>`}
function badge(text){return text?`<span class="product-badge ${/off|sale/i.test(text)?'sale':''}">${escapeHtml(text)}</span>`:''}
function productCard(p,style=''){
  const loved=state.wishlist.includes(p.id),compared=state.compare.includes(p.id);
  return `<article class="product-card ${style}">
    <div class="product-picture"><a href="#/product/${p.id}" aria-label="View ${escapeHtml(p.name)}"><img src="${asset(p.image)}" alt="${escapeHtml(p.name)}" loading="lazy" /></a>
      ${badge(p.badge)}<div class="product-actions"><button title="${loved?'Remove from':'Add to'} wishlist" aria-label="${loved?'Remove from':'Add to'} wishlist" class="round-icon ${loved?'selected':''}" data-action="wishlist" data-id="${p.id}">${ic('heart',18)}</button><button title="Quick view" aria-label="Quick view ${escapeHtml(p.name)}" class="round-icon" data-action="quick" data-id="${p.id}">${ic('upRight',18)}</button><button title="${compared?'Remove from compare':'Compare product'}" aria-label="Compare ${escapeHtml(p.name)}" class="round-icon ${compared?'selected':''}" data-action="compare" data-id="${p.id}">${ic('compare',18)}</button></div>
      <button class="product-add" data-action="add" data-id="${p.id}" ${p.stock<=0?'disabled':''}>${ic('plus',16)} ${p.stock<=0?'Out of stock':'Add to bag'}</button>
    </div>
    <div class="product-info"><div class="product-kicker">${escapeHtml(p.category)} <span class="tiny-dot"></span> ${stars(p.rating)}</div><a href="#/product/${p.id}" class="product-name">${escapeHtml(p.name)}</a><div class="product-prices"><b>${money(p.price)}</b>${p.compareAt?`<s>${money(p.compareAt)}</s>`:''}</div></div>
  </article>`;
}
function renderHeader(){return `<div class="announcement">A little something extra — <b>10% off your first order</b> with code <strong>FORM10</strong><a href="#/shop">Explore the store ${ic('arrow',13)}</a></div>
<header class="site-header"><div class="header-inner container">
  <button class="mobile-menu-toggle icon-button" aria-label="Open menu" data-action="mobile">${ic('menu',23)}</button>
  <a href="#/" class="wordmark" aria-label="FORMA home">forma<span>.</span></a>
  <nav class="main-nav" aria-label="Main navigation"><a href="#/shop">Shop all</a><a href="#/shop?sort=newest">New arrivals</a><a href="#/collections">Collections</a><a href="#/about">Our story</a></nav>
  <div class="header-tools"><button class="header-search-trigger" data-action="focusSearch">${ic('search',19)} <span>What are you looking for?</span> <span class="search-shortcut">⌘ K</span></button>
    <div class="header-icons">${iconButton('heart','Wishlist',`data-action="goWishlist"`)}${iconButton('user','Your account',`data-action="goAccount"`)}<button class="icon-button bag-toggle" data-action="cart" aria-label="Open shopping bag">${ic('bag',22)}<span class="cart-counter" id="cart-count">${cartCount()}</span></button></div>
  </div>
</div></header>`}
function renderFooter(){return `<footer class="footer"><div class="container"><div class="footer-main"><div class="footer-brand"><a href="#/" class="wordmark light">forma<span>.</span></a><p>Things that make everyday feel extraordinary. Designed with intention, made to last.</p><div class="footer-social"><a href="https://github.com" target="_blank" rel="noopener" aria-label="GitHub">GH</a><a href="https://instagram.com" target="_blank" rel="noopener" aria-label="Instagram">${ic('instagram',17)}</a></div></div>
<div class="footer-col"><h4>Explore</h4><a href="#/shop">Shop all</a><a href="#/shop?sort=newest">New arrivals</a><a href="#/collections">Collections</a><a href="#/wishlist">Wishlist</a></div>
<div class="footer-col"><h4>Support</h4><a href="#/about#faq">Shipping & returns</a><a href="#/about#faq">FAQs</a><a href="#/account">Track your order</a><a href="mailto:hello@forma.example">Contact us</a></div>
<div class="footer-col"><h4>Company</h4><a href="#/about">Our story</a><a href="#/about">Our philosophy</a><a href="#/admin">Admin demo</a><a href="https://github.com" target="_blank" rel="noopener">GitHub</a></div></div>
<div class="footer-bottom"><span>© ${new Date().getFullYear()} FORMA. A concept portfolio project.</span><div class="payment-pills"><span>VISA</span><span>mastercard</span><span>AMEX</span><span>PayPal</span></div><span>Made thoughtfully <span class="footer-heart">♥</span></span></div></div></footer>`}
function sectionHeading(eyebrow,title,subtitle,link='#/shop',linkText='View all products'){return `<div class="section-header"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${link?`<a class="subtle-link" href="${link}">${linkText} ${ic('arrow',18)}</a>`:''}</div>`}
function renderBenefits(){return `<div class="benefits container"><div class="benefit">${ic('truck',24)}<div><b>Free delivery</b><span>On orders over $150</span></div></div><div class="benefit">${ic('return',24)}<div><b>Easy returns</b><span>30 days to decide</span></div></div><div class="benefit">${ic('shield',24)}<div><b>Made to last</b><span>Thoughtfully selected</span></div></div><div class="benefit">${ic('gift',24)}<div><b>A little extra</b><span>Gifts with every order*</span></div></div></div>`}
function renderHome(){const featured=products().filter(p=>p.featured).slice(0,4);const arrivals=products().slice(4,12);
  return `<main>
  <section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="hero-index"><span class="hero-index-line"></span> THE FORMA EDIT — VOL. 01</div>
    <h1>Design your<br/><em>everyday.</em></h1><p>Considered objects for curious minds and inspired spaces. Discover everyday essentials worth loving for a long time.</p><div class="hero-ctas"><a class="btn btn-dark" href="#/shop">Explore the collection ${ic('upRight',17)}</a><a href="#/about" class="text-link">Discover our story ${ic('arrow',17)}</a></div>
    <div class="hero-social-proof"><div class="avatar-stack"><span>J</span><span>M</span><span>A</span><span>K</span></div><div><span class="star-gold">★★★★★</span><small>Loved by design enthusiasts</small></div></div>
  </div><div class="hero-visual"><span class="hero-orbit orbit-one"></span><span class="hero-orbit orbit-two"></span><div class="hero-art-circle"></div><img class="hero-image" src="${asset('chair')}" alt="Solstice lounge chair from the curated collection" /><div class="hero-floating-card"><span class="floating-label">THE OBJECT OF THE MONTH</span><strong>Solstice Lounge Chair</strong><span>Comfort in every curve ${ic('arrow',14)}</span></div><span class="hero-side-label">FORM / FUNCTION / FEELING</span></div>
  </div><div class="hero-bottom"><div class="container hero-bottom-inner"><span>01 / 04 — THE COLLECTION</span><span>Scroll to discover ${ic('down',16)}</span></div></div></section>
  ${renderBenefits()}
  <section class="section-space container" id="collections">${sectionHeading('THE CURATED COLLECTION','Find your kind of <em>good.</em>','Explore pieces by the moments they make better.', '#/collections','Discover collections')}
  <div class="category-grid">${categoryInfo.map(c=>`<a href="#/shop?category=${encodeURIComponent(c.name)}" class="category-card cat-${c.tone}"><div class="category-copy"><span>${c.count}</span><h3>${c.name}</h3><p>${c.subtitle}</p><span class="category-arrow">${ic('upRight',20)}</span></div><img src="${asset(c.image)}" alt="${c.name} collection" loading="lazy" /></a>`).join('')}</div></section>
  <section class="section-space container bestsellers">${sectionHeading('GOOD THINGS, GREAT REVIEWS','The crowd <em>favorites.</em>','The pieces everyone keeps coming back to.')}
   <div class="product-grid home-products">${featured.map(p=>productCard(p)).join('')}</div></section>
  <section class="editorial"><div class="container editorial-inner"><div class="editorial-photo"><div class="editorial-image-back"></div><img src="${asset('headphones-sand')}" alt="Sand wireless headphones" loading="lazy"/><span class="editorial-corner-mark">01 — AUDIO</span></div><div class="editorial-text"><span class="eyebrow light-eyebrow">THE SOUND OF SLOWING DOWN</span><h2>Less noise.<br/><em>More living.</em></h2><p>Because the best moments deserve your full attention. Meet sound designed to bring you closer to what matters.</p><a href="#/shop?category=Audio" class="btn btn-cream">Explore audio ${ic('upRight',17)}</a><span class="editorial-giant">THE QUIET EDIT</span></div></div></section>
  <section class="section-space container new-arrivals">${sectionHeading('FRESH FINDS','New in, <em>just for you.</em>','Your next favorite thing might be right here.','#/shop?sort=newest','Explore all new arrivals')}
  <div class="product-grid">${arrivals.map(p=>productCard(p)).join('')}</div><div class="centered-action"><a href="#/shop" class="btn btn-outline">View the full collection ${ic('arrow',17)}</a></div></section>
  <section class="feature-strip"><div class="container feature-inner"><div class="feature-words"><span class="eyebrow">THE FORMA PHILOSOPHY</span><h2>Thoughtful things.<br/><em>Meaningful moments.</em></h2><p>We believe in buying fewer, better things—and making a little more space for what truly matters.</p><a href="#/about" class="subtle-link">More about us ${ic('arrow',18)}</a></div><div class="feature-sculpture"><img src="${asset('lamp')}" alt="Sculptural modern table lamp" loading="lazy" /><div class="feature-decoration">F<span>.</span></div></div></div></section>
  ${renderNewsletter()}
  </main>`;
}
function renderNewsletter(){return `<section class="newsletter"><div class="container newsletter-inner"><div><span class="eyebrow">THE GOOD LIST</span><h2>A little more <em>inspired.</em></h2><p>New arrivals, considered ideas and a little extra something, delivered occasionally.</p></div><form id="newsletter-form" class="newsletter-form"><label class="sr-only" for="newsletter-email">Email address</label><input type="email" id="newsletter-email" name="email" placeholder="Your email address" required autocomplete="email"/><button type="submit">Join the list ${ic('arrow',17)}</button><small>Just the good stuff. Unsubscribe whenever you like.</small></form></div></section>`}
function renderCollections(){return `<main><div class="page-hero simple-page-hero container"><span class="eyebrow">EXPLORE OUR WORLD</span><h1>Collections, <em>considered.</em></h1><p>From the first coffee of the morning to the final song at night, find pieces that make your moments.</p></div><section class="container collections-page">${categoryInfo.map((c,i)=>`<a href="#/shop?category=${c.name}" class="collection-row collection-${i%2?'reverse':'normal'}"><div class="collection-visual cat-${c.tone}"><img src="${asset(c.image)}" alt="${c.name} curated collection"/></div><div class="collection-description"><span class="eyebrow">COLLECTION 0${i+1}</span><h2>${c.name}<em>.</em></h2><p>${c.subtitle}. Carefully chosen essentials that look as good as they feel, crafted to belong in your everyday.</p><span class="subtle-link">Shop ${c.name.toLowerCase()} ${ic('arrow',17)}</span></div></a>`).join('')}</section>${renderNewsletter()}</main>`}
function renderShop(){let list=filteredProducts();const total=list.length;const pageSize=12;let maxPage=Math.max(1,Math.ceil(total/pageSize));state.shop.page=Math.min(maxPage,state.shop.page);const shown=list.slice((state.shop.page-1)*pageSize,state.shop.page*pageSize);
  return `<main><section class="shop-top"><div class="container"><div class="breadcrumb"><a href="#/">Home</a>${ic('chevron',13)}<span>Shop all</span></div><div class="shop-top-main"><div><span class="eyebrow">YOUR EVERYDAY, ELEVATED</span><h1>Explore the <em>collection.</em></h1><p>Good design is for living. Find something that feels like you.</p></div><div class="shop-result-graphic">FORM / 2026<span>©</span></div></div></div></section>
  <section class="container shop-layout"><aside class="shop-sidebar" id="shop-sidebar"><div class="shop-sidebar-heading"><h3>Filters</h3><button class="clear-filters" data-action="clearFilters">Clear all</button></div>
  <div class="filter-block"><h4>Category ${ic('down',16)}</h4>${['All',...categoryInfo.map(c=>c.name)].map(c=>`<button class="filter-option ${state.shop.category===c?'active':''}" data-action="category" data-value="${c}"><span class="filter-radio"></span>${c==='All'?'All products':c}<span>${c==='All'?products().length:products().filter(p=>p.category===c).length}</span></button>`).join('')}</div>
  <div class="filter-block"><h4>Price range ${ic('down',16)}</h4><div class="price-inputs"><span>$0</span><strong id="price-range-value">${money(state.shop.price)}+</strong></div><input type="range" min="40" max="650" step="10" value="${state.shop.price}" id="price-slider" aria-label="Maximum price"/><div class="price-labels"><span>$40</span><span>$650+</span></div></div>
  <div class="filter-block"><h4>Offers ${ic('down',16)}</h4><label class="sale-filter"><input id="sale-only" type="checkbox" ${state.shop.onlySale?'checked':''}><span>On sale only</span></label></div>
  <div class="sidebar-help"><span>${ic('gift',21)}</span><b>A little treat on us.</b><p>Use FORM10 to save 10% on your first demo order.</p></div></aside>
  <div class="shop-main"><div class="shop-toolbar"><div class="shop-left-toolbar"><button class="mobile-filter-toggle" data-action="toggleFilters">${ic('filters',17)} Filters</button><span id="results-count">Showing ${total} ${total===1?'product':'products'}</span></div><div class="shop-right-toolbar"><label for="shop-sort" class="sr-only">Sort products</label><select id="shop-sort"><option value="featured" ${state.shop.sort==='featured'?'selected':''}>Featured</option><option value="newest" ${state.shop.sort==='newest'?'selected':''}>New arrivals</option><option value="price-low" ${state.shop.sort==='price-low'?'selected':''}>Price: low to high</option><option value="price-high" ${state.shop.sort==='price-high'?'selected':''}>Price: high to low</option><option value="rating" ${state.shop.sort==='rating'?'selected':''}>Top rated</option></select><span class="toolbar-divider"></span><button class="view-btn ${state.shop.grid===3?'selected':''}" data-action="grid" data-value="3" title="3-column view">${ic('grid',17)}</button><button class="view-btn ${state.shop.grid===2?'selected':''}" data-action="grid" data-value="2" title="2-column view">${ic('list',17)}</button></div></div>
  <div class="active-filters">${state.shop.category!=='All'?`<button data-action="category" data-value="All">${state.shop.category} ${ic('close',13)}</button>`:''}${state.shop.query?`<button data-action="clearQuery">Search: ${escapeHtml(state.shop.query)} ${ic('close',13)}</button>`:''}${state.shop.onlySale?`<button data-action="removeSale">On sale ${ic('close',13)}</button>`:''}</div>
  ${shown.length?`<div class="product-grid shop-products columns-${state.shop.grid}">${shown.map(p=>productCard(p)).join('')}</div>`:renderEmpty('No pieces found','Try changing your filters or searching for something else.','Reset filters','#/shop','clearFilters')}
  ${maxPage>1?`<div class="pagination">${Array.from({length:maxPage},(_,i)=>i+1).map(n=>`<button class="${n===state.shop.page?'current':''}" data-action="page" data-value="${n}">${n}</button>`).join('')}</div>`:''}
  </div></section></main>`;
}
function filteredProducts(){let p=products().filter(p=>(state.shop.category==='All'||p.category===state.shop.category)&&p.price<=state.shop.price&&(state.shop.onlySale?!!p.compareAt:true)&&(!state.shop.query||`${p.name} ${p.category} ${p.tag}`.toLowerCase().includes(state.shop.query.toLowerCase())));
  switch(state.shop.sort){case 'newest':p.sort((a,b)=>b.id-a.id);break;case 'price-low':p.sort((a,b)=>a.price-b.price);break;case 'price-high':p.sort((a,b)=>b.price-a.price);break;case 'rating':p.sort((a,b)=>b.rating-a.rating);break;default:p.sort((a,b)=>Number(!!b.featured)-Number(!!a.featured));}
  return p;
}
function renderProduct(id){const p=getProduct(id);if(!p)return renderNotFound();const related=products().filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4);const isWish=state.wishlist.includes(p.id);
 return `<main class="product-page"><div class="container"><div class="breadcrumb product-bread"><a href="#/">Home</a>${ic('chevron',13)}<a href="#/shop?category=${p.category}">${escapeHtml(p.category)}</a>${ic('chevron',13)}<span>${escapeHtml(p.name)}</span></div>
 <div class="detail-layout"><div class="detail-gallery"><div class="detail-main-img"><img id="detail-image" src="${asset(p.image)}" alt="${escapeHtml(p.name)}"/>${badge(p.badge)}<button class="detail-zoom" data-action="quick" data-id="${p.id}" title="Quick view">${ic('search',18)}</button></div><div class="thumb-strip"><button class="detail-thumb active" data-action="thumb" data-value="a"><img src="${asset(p.image)}" alt="Primary view"/></button><button class="detail-thumb thumb-lighter" data-action="thumb" data-value="b"><img src="${asset(p.image)}" alt="Light studio view"/></button><button class="detail-thumb thumb-darker" data-action="thumb" data-value="c"><img src="${asset(p.image)}" alt="Dark studio view"/></button></div></div>
 <div class="detail-body"><div class="detail-kicker">THE FORMA COLLECTION <span> / ${escapeHtml(p.category.toUpperCase())}</span></div><h1>${escapeHtml(p.name)}</h1><div class="detail-review">${stars(p.rating)} <span>${p.reviews} reviews</span><span class="tiny-dot"></span><span>${p.stock>0?'In stock':'Out of stock'}</span></div><div class="detail-price">${money(p.price)}${p.compareAt?`<s>${money(p.compareAt)}</s><span class="detail-save">Save ${Math.round((p.compareAt-p.price)/p.compareAt*100)}%</span>`:''}</div><p class="detail-lead">${escapeHtml(p.detail)}</p>
 <div class="detail-variant"><div><b>Color</b><span id="color-label">${escapeHtml(p.colors?.[0]||'Default')}</span></div><div class="swatches">${(p.colors||['Default']).map((color,i)=>`<button class="swatch ${i===0?'active':''}" style="--swatch:${colorHex(color)}" title="${escapeHtml(color)}" aria-label="Choose ${escapeHtml(color)}" data-action="color" data-value="${escapeHtml(color)}"></button>`).join('')}</div></div>
 <div class="detail-qty-label"><b>Quantity</b><span>${p.stock<10?`Only ${p.stock} left`:'Ready to ship'}</span></div><div class="detail-purchase"><div class="qty-control"><button aria-label="Decrease quantity" data-action="detailQty" data-value="-1">${ic('minus',15)}</button><strong id="detail-qty">1</strong><button aria-label="Increase quantity" data-action="detailQty" data-value="1">${ic('plus',15)}</button></div><button class="btn btn-dark detail-add" data-action="detailAdd" data-id="${p.id}" ${p.stock<=0?'disabled':''}>${ic('bag',19)} ${p.stock<=0?'Out of stock':'Add to bag'}</button><button class="detail-heart ${isWish?'liked':''}" data-action="wishlist" data-id="${p.id}" title="Wishlist">${ic('heart',22)}</button></div>
 <div class="buy-now-row"><button class="buy-now-btn" data-action="buyNow" data-id="${p.id}">Buy now ${ic('arrow',17)}</button></div>
 <div class="delivery-box"><div>${ic('truck',22)}<p><b>Free shipping over $150</b><small>Standard delivery in 3–7 business days (demo)</small></p></div><div>${ic('return',22)}<p><b>30-day easy returns</b><small>Keep what you love. Return what you don't.</small></p></div></div>
 <div class="detail-accordion"><details open><summary>Product details ${ic('plus',18)}</summary><p>${escapeHtml(p.tag)}</p></details><details><summary>Specifications ${ic('plus',18)}</summary><ul>${(p.specs||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></details><details><summary>Shipping & returns ${ic('plus',18)}</summary><p>Free demo shipping over $150. All delivery times and policies shown are illustrative for this portfolio project.</p></details></div>
 </div></div></div>
 <section class="container section-space detail-related">${sectionHeading('MORE TO LOVE','You might also <em>like.</em>','A few more good things for your list.',`#/shop?category=${p.category}`,'Explore category')}<div class="product-grid">${related.map(x=>productCard(x)).join('')}</div></section></main>`;
}
function variantImageFor(image,color){const variants={headphones:{Sand:'headphones-sand'},speaker:{Linen:'speaker-cream'},lamp:{Midnight:'lamp-black'},sneaker:{Forest:'sneaker-dark'},backpack:{Black:'backpack-black'},bottle:{Rose:'bottle-rose'}};return variants[image]?.[color]||image}
function colorHex(color){return ({Graphite:'#3a3c3d',Sand:'#d8c2aa',Charcoal:'#333836',Linen:'#b6ae9c',Stone:'#b8aca0',Midnight:'#252b2b',Champagne:'#c7b69c',Onyx:'#303335',Oat:'#d6c6ad',Forest:'#465e4d',Sage:'#94a78c',Black:'#242727',Smoke:'#545b5b',Rose:'#c8a29f',Pearl:'#e5ddd2',Camel:'#aa8970',Natural:'#dfd1b6',Ivory:'#e3e0d4',Amber:'#cba17a',Silver:'#a7aeb0'})[color]||'#cbc5bd'}
function renderEmpty(title,desc,cta='Shop the collection',url='#/shop',action=''){return `<div class="empty-state"><div class="empty-orb">${ic('bag',40)}</div><h2>${title}</h2><p>${desc}</p>${action?`<button class="btn btn-dark" data-action="${action}">${cta} ${ic('arrow',17)}</button>`:`<a class="btn btn-dark" href="${url}">${cta} ${ic('arrow',17)}</a>`}</div>`}
function renderWishlist(){const saved=state.wishlist.map(getProduct).filter(Boolean);return `<main class="container inner-page"><div class="page-intro"><span class="eyebrow">YOUR LITTLE COLLECTION</span><h1>Saved with <em>love.</em></h1><p>All the things you've had your eye on, in one lovely place.</p></div>${saved.length?`<div class="wishlist-count">${saved.length} ${saved.length===1?'saved item':'saved items'}</div><div class="product-grid shop-products">${saved.map(p=>productCard(p)).join('')}</div>`:renderEmpty('Your wishlist is waiting.','See something you like? Tap the heart and save it for later.')}</main>`}
function renderCompare(){const list=state.compare.map(getProduct).filter(Boolean);return `<main class="container inner-page"><div class="page-intro"><span class="eyebrow">A CLOSER LOOK</span><h1>Compare your <em>favorites.</em></h1><p>Good choices deserve a little consideration. Compare up to three pieces side by side.</p></div>${!list.length?renderEmpty('Nothing to compare yet.','Add products using the compare icon on any product card.'): `<div class="compare-scroller"><table class="compare-table"><thead><tr><th>Feature</th>${list.map(p=>`<th><img src="${asset(p.image)}" alt="${escapeHtml(p.name)}"/><a href="#/product/${p.id}">${escapeHtml(p.name)}</a><button data-action="compare" data-id="${p.id}" class="compare-remove">${ic('close',14)} Remove</button></th>`).join('')}</tr></thead><tbody>${[['Price',p=>money(p.price)],['Category',p=>p.category],['Customer rating',p=>p.rating+' / 5'],['Availability',p=>p.stock>0?'In stock':'Out of stock'],['Description',p=>p.tag]].map(([label,fn])=>`<tr><th>${label}</th>${list.map(p=>`<td>${escapeHtml(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th></th>${list.map(p=>`<td><button class="btn btn-dark btn-small" data-action="add" data-id="${p.id}">Add to bag</button></td>`).join('')}</tr></tbody></table></div>`}</main>`}
function renderAccount(){const orders=[...state.orders].reverse();return `<main class="container inner-page"><div class="page-intro"><span class="eyebrow">YOUR SPACE</span><h1>Hello, <em>you.</em></h1><p>Take a look at your orders on this device.</p></div><div class="account-intro">${ic('info',21)} <p>This is a portfolio demo. Orders are stored in your browser only, without a real customer account or a payment.</p></div><div class="orders-heading"><h2>Order history <small>(${orders.length})</small></h2><a class="subtle-link" href="#/shop">Continue shopping ${ic('arrow',18)}</a></div>${orders.length?`<div class="order-list">${orders.map(order=>`<article class="order-card"><div class="order-header"><div><b>${escapeHtml(order.id)}</b><span>${new Date(order.date).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</span></div><span class="order-status">${escapeHtml(order.status||'Placed')}</span></div><div class="order-items">${order.items.map(item=>{const p=getProduct(item.id);return `<div><img src="${asset(p?.image||'tote')}" alt=""/><span>${escapeHtml(item.name)} <small>${escapeHtml(item.variant||'')} · Qty: ${item.quantity}</small></span><strong>${money(item.price*item.quantity)}</strong></div>`}).join('')}</div><div class="order-total">Order total <strong>${money(order.total)}</strong></div></article>`).join('')}</div>`:renderEmpty('No orders just yet.','Your future favorites are a few clicks away.')}</main>`}
function renderCheckout(){if(state.checkoutDone){const o=state.checkoutDone;return `<main class="container checkout-success"><div class="success-check">${ic('check',42)}</div><span class="eyebrow">ORDER CONFIRMED</span><h1>Good things are <em>on their way.</em></h1><p>Thanks for shopping the FORMA demo! Your order <strong>${escapeHtml(o.id)}</strong> was saved in this browser. No payment was collected and no delivery will occur.</p><div class="success-receipt"><div><span>Order number</span><b>${escapeHtml(o.id)}</b></div><div><span>Items purchased</span><b>${o.items.reduce((s,i)=>s+i.quantity,0)}</b></div><div><span>Order total</span><b>${money(o.total)}</b></div><div><span>Demo payment</span><b>Not charged</b></div></div><div class="success-actions"><a href="#/shop" class="btn btn-dark">Keep exploring ${ic('arrow',17)}</a><a href="#/account" class="btn btn-outline">View order history</a></div></main>`}
 if(!state.cart.length)return `<main class="container inner-page">${renderEmpty('Your bag is empty.','Add something you love before checking out.')}</main>`;
 return `<main class="checkout-page container"><a href="#/shop" class="checkout-back">${ic('chevronLeft',16)} Continue shopping</a><div class="checkout-page-title"><span class="eyebrow">ONE STEP CLOSER</span><h1>Your <em>checkout.</em></h1><p>Fill in your details to place a demo order.</p></div><div class="checkout-banner">${ic('info',20)} Demo checkout only — no real payment is accepted or processed.</div>
 <div class="checkout-layout"><form id="checkout-form" class="checkout-form">
 <div class="checkout-section"><div class="checkout-section-heading"><span>01</span><h2>Contact information</h2></div><div class="form-grid"><label class="full">Email address <input name="email" type="email" placeholder="you@example.com" autocomplete="email" required maxlength="150"/></label></div></div>
 <div class="checkout-section"><div class="checkout-section-heading"><span>02</span><h2>Shipping address</h2></div><div class="form-grid"><label>First name <input name="firstName" placeholder="First name" required autocomplete="given-name" maxlength="80"/></label><label>Last name <input name="lastName" placeholder="Last name" required autocomplete="family-name" maxlength="80"/></label><label class="full">Street address <input name="address" placeholder="123 Example Street" required autocomplete="street-address" maxlength="180"/></label><label>City <input name="city" placeholder="Your city" required autocomplete="address-level2" maxlength="80"/></label><label>Postal / ZIP code <input name="postal" placeholder="Postal code" required autocomplete="postal-code" maxlength="30"/></label><label class="full">Country / region <select name="country" required><option value="">Select country</option><option>Sri Lanka</option><option>United States</option><option>United Kingdom</option><option>Canada</option><option>Australia</option><option>India</option><option>Other</option></select></label></div></div>
 <div class="checkout-section"><div class="checkout-section-heading"><span>03</span><h2>Demo payment</h2></div><label class="demo-payment"><input type="radio" name="payment" value="demo" checked><span>${ic('shield',21)} <b>Demo payment — no charge</b><small>Click below to create a sample order. Never enter real card details.</small></span></label></div>
 <button class="btn btn-dark checkout-place" type="submit">Place demo order ${ic('arrow',17)}</button><p class="checkout-small-print">By placing this order, you understand this is a portfolio demonstration with no real shipment.</p>
 </form><aside class="checkout-summary"><h2>Order summary <span>(${cartCount()})</span></h2><div class="summary-products">${state.cart.map(item=>{const p=getProduct(item.id);return p?`<div class="summary-item"><div class="summary-thumb"><img src="${asset(p.image)}" alt=""/><span>${item.quantity}</span></div><div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(item.variant||p.category)}</small></div><strong>${money(p.price*item.quantity)}</strong></div>`:''}).join('')}</div>
 <form id="coupon-form" class="coupon-form"><label class="sr-only" for="coupon-input">Discount code</label><input id="coupon-input" name="coupon" placeholder="Discount code" value="${escapeHtml(state.coupon)}"/><button type="submit">Apply</button></form>
 <div class="summary-prices"><div>Subtotal <span>${money(cartSubtotal())}</span></div>${discount()?`<div class="discount-text">Discount (FORM10) <span>−${money(discount())}</span></div>`:''}<div>Shipping <span>${cartShipping()===0?'Free':money(cartShipping())}</span></div><div class="summary-total">Total <strong>${money(cartTotal())}</strong></div></div><div class="summary-safe">${ic('lock',16)} Secure-looking demo · No actual payment</div></aside></div></main>`;
}
function renderAbout(){return `<main><section class="about-hero"><div class="container about-hero-inner"><span class="eyebrow">WHY FORMA EXISTS</span><h1>Less, but <em>better.</em></h1><p>We believe the objects we choose shape the way we live. So we make space for fewer things—and better stories.</p></div></section><section class="container about-content"><div class="about-statement"><span class="eyebrow">OUR APPROACH</span><h2>Beautifully useful.<br/><em>Quietly intentional.</em></h2></div><div class="about-explanation"><p>FORMA is a fictional lifestyle concept created as a portfolio project. It's designed around one simple idea: everyday objects should spark more joy than clutter.</p><p>From considered essentials to timeless details, this concept celebrates clarity, comfort, and the little moments in between.</p><a href="#/shop" class="subtle-link">Explore our collection ${ic('arrow',17)}</a></div></section><section class="container values-grid"><div>${ic('sparkle',26)}<h3>Choose intentionally</h3><p>Less scrolling, more thoughtful choices. Quality of experience matters.</p></div><div>${ic('shield',26)}<h3>Design for everyday</h3><p>Practical things can—and should—feel beautiful.</p></div><div>${ic('return',26)}<h3>Keep it simple</h3><p>Considered interactions, honest information and a calm place to shop.</p></div></section><section id="faq" class="container faq-section"><span class="eyebrow">GOOD TO KNOW</span><h2>Questions, <em>answered.</em></h2><details><summary>Is FORMA a real store? ${ic('plus',19)}</summary><p>No. FORMA is a fully interactive portfolio project. Product listings, testimonials and policies are illustrative. Orders are demonstrations and no real deliveries occur.</p></details><details><summary>Can I pay for an order? ${ic('plus',19)}</summary><p>No real payments are supported. The checkout flow creates a local demo order and does not ask for payment details.</p></details><details><summary>Are my details stored online? ${ic('plus',19)}</summary><p>They stay in your browser's local storage. This is a front-end demo and does not send submitted order details to a server.</p></details><details><summary>How do I view the admin dashboard? ${ic('plus',19)}</summary><p>Select “Admin demo” from the footer and sign in with the sample credentials documented on the login page. All dashboard changes are local to your browser.</p></details></section>${renderNewsletter()}</main>`}
function renderNotFound(){return `<main class="container inner-page">${renderEmpty('Well, this is unexpected.','We couldn\'t find the page you were looking for.','Back to home','#/')}</main>`}

function renderCartDrawer(){return `<div class="overlay-backdrop" data-action="closeOverlay"></div><aside class="cart-drawer" role="dialog" aria-modal="true" aria-label="Shopping bag"><div class="drawer-head"><div><span class="eyebrow">YOUR FAVORITE FINDS</span><h2>Your bag <span>(${cartCount()})</span></h2></div><button class="icon-button" aria-label="Close bag" data-action="closeOverlay">${ic('close',23)}</button></div>
 ${state.cart.length?`<div class="drawer-scroll"><div class="shipping-goal">${cartSubtotal()>=150?`<div class="shipping-message">${ic('check',16)} You've unlocked free delivery!</div>`:`<div class="shipping-message">${ic('truck',17)} Add <b>${money(150-cartSubtotal())}</b> for free delivery</div>`}<div class="progress-track"><div style="width:${Math.min(100,cartSubtotal()/150*100)}%"></div></div></div>
 <div class="cart-items">${state.cart.map(item=>{const p=getProduct(item.id);if(!p)return '';return `<div class="cart-item"><a href="#/product/${p.id}" class="cart-item-image"><img src="${asset(p.image)}" alt="${escapeHtml(p.name)}" /></a><div class="cart-item-info"><a href="#/product/${p.id}" class="cart-item-name">${escapeHtml(p.name)}</a><span>${escapeHtml(item.variant||p.category)}</span><strong>${money(p.price*item.quantity)}</strong><div class="cart-item-controls"><div class="small-qty"><button data-action="cartQty" data-id="${p.id}" data-value="-1" aria-label="Decrease">${ic('minus',13)}</button><b>${item.quantity}</b><button data-action="cartQty" data-id="${p.id}" data-value="1" aria-label="Increase">${ic('plus',13)}</button></div><button class="cart-remove" data-action="removeCart" data-id="${p.id}" aria-label="Remove ${escapeHtml(p.name)}">${ic('trash',16)}</button></div></div></div>`}).join('')}</div></div>
 <div class="drawer-footer"><div class="drawer-promo">${ic('gift',17)} Use <b>FORM10</b> for 10% off your demo order</div><div class="drawer-subtotal"><span>Subtotal</span><strong>${money(cartSubtotal())}</strong></div><p>Shipping and discounts calculated at checkout.</p><a href="#/checkout" class="btn btn-dark checkout-trigger" data-action="closeOverlay">Checkout ${ic('arrow',17)}</a><button class="continue-shopping" data-action="closeOverlay">Continue shopping</button></div>`:`<div class="drawer-empty">${ic('bag',47)}<h3>Nothing in your bag yet.</h3><p>Your next favorite thing is waiting.</p><button class="btn btn-dark" data-action="closeOverlay">Explore the collection ${ic('arrow',17)}</button></div>`}</aside>`}
function renderQuickView(){const p=getProduct(state.quickView);if(!p)return '';return `<div class="overlay-backdrop" data-action="closeOverlay"></div><div class="quick-modal" role="dialog" aria-modal="true" aria-label="Quick view ${escapeHtml(p.name)}"><button class="quick-close" data-action="closeOverlay" aria-label="Close quick view">${ic('close',22)}</button><div class="quick-image"><img src="${asset(p.image)}" alt="${escapeHtml(p.name)}"/></div><div class="quick-content"><span class="eyebrow">${escapeHtml(p.category.toUpperCase())} / THE COLLECTION</span><h2>${escapeHtml(p.name)}</h2><div>${stars(p.rating)} <small>(${p.reviews} reviews)</small></div><strong class="quick-price">${money(p.price)} ${p.compareAt?`<s>${money(p.compareAt)}</s>`:''}</strong><p>${escapeHtml(p.detail)}</p><button class="btn btn-dark" data-action="add" data-id="${p.id}">Add to bag ${ic('bag',18)}</button><a href="#/product/${p.id}" data-action="closeOverlay" class="subtle-link">See full details ${ic('arrow',17)}</a></div></div>`}
function renderSearchOverlay(){return `<div class="overlay-backdrop" data-action="closeOverlay"></div><div class="search-modal" role="dialog" aria-modal="true" aria-label="Search the store"><div class="search-input-row">${ic('search',24)}<input id="global-search" placeholder="Search for something wonderful..." aria-label="Search products" autocomplete="off"/><button class="icon-button" data-action="closeOverlay" aria-label="Close search">${ic('close',21)}</button></div><div class="search-suggestions"><span class="eyebrow">POPULAR SEARCHES</span><div>${['Headphones','Lamp','Backpack','Desk','Sneakers'].map(term=>`<button data-action="popularSearch" data-value="${term}">${ic('search',14)} ${term}</button>`).join('')}</div><p>Try searching by a product name or collection.</p></div></div>`}
function renderMobileNav(){return `<div class="overlay-backdrop" data-action="closeOverlay"></div><nav class="mobile-nav" aria-label="Mobile navigation"><div><a href="#/" class="wordmark">forma<span>.</span></a><button class="icon-button" data-action="closeOverlay" aria-label="Close menu">${ic('close',23)}</button></div><a href="#/shop">Shop all ${ic('arrow',19)}</a><a href="#/shop?sort=newest">New arrivals ${ic('arrow',19)}</a><a href="#/collections">Collections ${ic('arrow',19)}</a><a href="#/about">Our story ${ic('arrow',19)}</a><a href="#/wishlist">Wishlist ${ic('heart',19)}</a><a href="#/account">My account ${ic('user',19)}</a></nav>`}

