function adminLogin(){return `<main class="admin-login-page"><div class="admin-login-box"><a class="wordmark" href="#/">forma<span>.</span></a><div class="admin-login-icon">${ic('lock',24)}</div><span class="eyebrow">STORE MANAGEMENT</span><h1>Welcome <em>back.</em></h1><p>Sign in to explore the interactive admin dashboard.</p><form id="admin-login"><label>Email address<input name="email" type="email" value="admin@forma.demo" required /></label><label>Password<input name="password" type="password" placeholder="Demo password" required/></label><button class="btn btn-dark" type="submit">Sign in to dashboard ${ic('arrow',17)}</button><span id="login-error" class="login-error"></span></form><div class="demo-credentials">${ic('info',17)} <div><b>Demo credentials</b><span>admin@forma.demo / demo1234</span><small>This is a front-end simulation, not secure authentication.</small></div></div><a href="#/" class="back-store">${ic('chevronLeft',17)} Back to storefront</a></div></main>`}
function adminMetric(label,value,change,icon){return `<div class="admin-metric"><div class="metric-title">${label}<span>${ic(icon,20)}</span></div><strong>${value}</strong><small>${change}</small></div>`}
function renderAdmin(){if(!state.adminAuthorized)return adminLogin();const orders=adminOrders();const revenue=orders.reduce((s,o)=>s+o.total,0);const selected=state.adminView;
return `<main class="admin-app"><aside class="admin-sidebar"><div class="admin-brand"><a href="#/" class="wordmark light">forma<span>.</span></a><small>MANAGEMENT STUDIO</small></div><div class="admin-side-section"><span>WORKSPACE</span>${[['overview','grid','Overview'],['orders','bag','Orders'],['products','box','Products'],['customers','people','Customers']].map(([id,icon,label])=>`<button class="admin-nav-item ${selected===id?'active':''}" data-action="adminView" data-value="${id}">${ic(icon,18)} ${label}${id==='orders'?`<span>${orders.length}</span>`:''}</button>`).join('')}</div><div class="admin-side-bottom"><a href="#/" class="admin-nav-item">${ic('upRight',18)} View storefront</a><button class="admin-nav-item" data-action="resetDemo">${ic('return',18)} Reset demo data</button><button class="admin-nav-item" data-action="adminLogout">${ic('logout',18)} Sign out</button><div class="admin-user"><span class="admin-avatar">AD</span><div><b>Store Admin</b><small>Demo workspace</small></div></div></div></aside>
<div class="admin-main"><header class="admin-topbar"><div><span>Workspace</span>${ic('chevron',14)}<b>${selected.charAt(0).toUpperCase()+selected.slice(1)}</b></div><span class="admin-live"><i></i> Demo environment</span></header>
<div class="admin-content">${selected==='overview'?`<div class="admin-welcome"><div><span class="eyebrow">YOUR STORE AT A GLANCE</span><h1>Welcome back, <em>Admin.</em></h1><p>Here's what's happening with your concept store today.</p></div><span class="admin-date">${new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span></div>
<div class="admin-metrics">${adminMetric('Total revenue',money(revenue),'+12.4% demo trend','chart')}${adminMetric('Orders placed',orders.length,'Across the sample store','bag')}${adminMetric('Active products',products().length,'Items in the catalog','box')}${adminMetric('Average order value',money(revenue/Math.max(1,orders.length)),'Based on demo orders','bolt')}</div>
<div class="admin-panels"><section class="admin-panel admin-chart-panel"><div class="admin-panel-head"><div><h2>Revenue overview</h2><p>Illustrative order activity</p></div><span>Last 7 periods</span></div>${renderChart(orders)}</section><section class="admin-panel"><div class="admin-panel-head"><div><h2>Top collections</h2><p>By catalog products</p></div></div><div class="category-bars">${categoryInfo.map((c,i)=>`<div><div><span>${c.name}</span><b>${products().filter(p=>p.category===c.name).length} products</b></div><span class="category-bar"><span style="width:${products().filter(p=>p.category===c.name).length/6*100}%;background:${['#c4b19e','#94a58e','#b6b8bc','#cba9a1'][i]}"></span></span></div>`).join('')}</div></section></div>
<section class="admin-panel admin-order-panel"><div class="admin-panel-head"><div><h2>Recent orders</h2><p>Latest activity in your demo store</p></div><button class="admin-outline-btn" data-action="adminView" data-value="orders">View all ${ic('arrow',16)}</button></div>${renderAdminTable(orders.slice(0,5))}</section>`:
selected==='orders'?`<div class="admin-section-heading"><div><span class="eyebrow">ORDER MANAGEMENT</span><h1>All <em>orders.</em></h1><p>Review sample and newly placed demo orders. Change their status locally.</p></div><span class="admin-count-chip">${orders.length} orders</span></div><section class="admin-panel admin-order-panel">${renderAdminTable(orders,true)}</section>`:
selected==='products'?`<div class="admin-section-heading"><div><span class="eyebrow">INVENTORY MANAGEMENT</span><h1>Your <em>products.</em></h1><p>Edit prices and stock, add products or hide items from the store.</p></div><button class="btn btn-dark btn-small" data-action="openProductEditor">${ic('plus',17)} Add product</button></div><section class="admin-panel inventory-panel"><div class="inventory-toolbar"><h2>Catalog <span>(${products().length})</span></h2><small>Changes save to this browser</small></div><div class="inventory-scroll"><table class="inventory-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>${products().map(p=>`<tr><td><div class="inventory-product"><img src="${asset(p.image)}" alt=""/><div><b>${escapeHtml(p.name)}</b><small>SKU · FM-${String(p.id).padStart(4,'0')}</small></div></div></td><td>${escapeHtml(p.category)}</td><td><strong>${money(p.price)}</strong></td><td><span class="stock-pill ${p.stock<10?'low-stock':''}">${p.stock} in stock</span></td><td><button data-action="editProduct" data-id="${p.id}" class="admin-icon-btn" title="Edit product">${ic('edit',17)}</button><button data-action="deleteProduct" data-id="${p.id}" class="admin-icon-btn danger" title="Hide product">${ic('trash',17)}</button></td></tr>`).join('')}</tbody></table></div></section>`:
`<div class="admin-section-heading"><div><span class="eyebrow">CUSTOMER INSIGHTS</span><h1>Your <em>audience.</em></h1><p>Sample customer information for illustrating the dashboard.</p></div></div><div class="admin-metrics">${adminMetric('Demo customers',orders.length,'One sample customer per order','people')}${adminMetric('Newsletter signups',state.newsletter.length,'Saved in your browser','mail')}${adminMetric('Returning visitors','—','Requires live analytics','chart')}</div><section class="admin-panel admin-customer-note">${ic('info',25)}<h2>No real customer database</h2><p>This portfolio project intentionally uses local demonstration data. A production store would require secure sign-in, an actual database and consent-aware analytics.</p></section>`}
</div></div></main>`;
}
function renderChart(orders){const vals=[246,329,185,470,312,589,438].map((v,i)=>v+state.orders.length*(i+1)*8);const max=Math.max(...vals);return `<div class="chart-wrap"><div class="chart-y"><span>${money(max)}</span><span>${money(max*.66)}</span><span>${money(max*.33)}</span><span>$0</span></div><div class="revenue-chart">${vals.map((v,i)=>`<div class="chart-column"><div class="chart-bar" style="height:${v/max*100}%" title="${money(v)}"></div><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div></div>`}
function renderAdminTable(orders,editable=false){return `<div class="admin-table-scroll"><table class="admin-orders-table"><thead><tr><th>Order</th><th>Date</th><th>Items</th><th>Total</th><th>Status</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${escapeHtml(o.id)}</b></td><td>${new Date(o.date).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</td><td>${o.items.reduce((s,i)=>s+i.quantity,0)} items</td><td><strong>${money(o.total)}</strong></td><td>${editable?`<select data-order="${escapeHtml(o.id)}" class="status-select" aria-label="Change status of ${escapeHtml(o.id)}">${['Processing','In transit','Delivered','Cancelled','Placed'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select>`:`<span class="admin-status ${o.status==='Delivered'?'delivered':o.status==='In transit'?'in-transit':'processing'}">${escapeHtml(o.status)}</span>`}</td></tr>`).join('')}</tbody></table></div>`}
function renderEditor(){const p=getProduct(state.editProductId);const edit=!!p;return `<div class="overlay-backdrop" data-action="closeOverlay"></div><div class="edit-modal" role="dialog" aria-modal="true" aria-label="${edit?'Edit':'Create'} product"><div class="edit-modal-heading"><div><span class="eyebrow">INVENTORY / ${edit?'EDIT':'NEW'}</span><h2>${edit?'Edit product':'Add a product'}</h2></div><button class="icon-button" data-action="closeOverlay" aria-label="Close editor">${ic('close',22)}</button></div><form id="editor-form"><label>Product name<input name="name" value="${escapeHtml(p?.name||'')}" required maxlength="100" placeholder="e.g. Nova Desk Lamp" /></label><div class="form-grid"><label>Category<select name="category">${categoryInfo.map(c=>`<option ${p?.category===c.name?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Image illustration<select name="image">${['headphones','speaker','lamp','watch','sneaker','backpack','sunglasses','bottle','mug','earbuds','chair','tote','keyboard','diffuser','camera','mouse','clock','stand'].map(s=>`<option ${p?.image===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Price ($)<input name="price" type="number" min="1" max="99999" step="0.01" value="${p?.price||99}" required/></label><label>Stock quantity<input name="stock" type="number" min="0" max="99999" value="${p?.stock??10}" required/></label></div><label>Short description<textarea name="detail" maxlength="400" required rows="3">${escapeHtml(p?.detail||'A thoughtfully designed piece for everyday living.')}</textarea></label><label>Badge<input name="badge" placeholder="New / Bestseller / Limited" maxlength="25" value="${escapeHtml(p?.badge||'New')}"/></label><button class="btn btn-dark" type="submit">${edit?'Save changes':'Create product'} ${ic('check',17)}</button></form></div>`}

function renderOverlay(){const ui=$('#ui-layer');ui.innerHTML=state.drawer==='cart'?renderCartDrawer():state.drawer==='search'?renderSearchOverlay():state.drawer==='quick'?renderQuickView():state.drawer==='editor'?renderEditor():state.mobileMenu?renderMobileNav():'';document.body.classList.toggle('overlay-open',!!(state.drawer||state.mobileMenu));if(state.drawer==='search')setTimeout(()=>$('#global-search')?.focus(),0);if(state.drawer)ui.querySelector('.cart-drawer button, .search-modal input, .quick-modal button, .edit-modal button')?.focus()}
function closeOverlay(){state.drawer=null;state.quickView=null;state.mobileMenu=false;renderOverlay()}
function routePath(){return decodeURIComponent((location.hash||'#/').slice(1).split('?')[0].split('#')[0])||'/'}
function parseRouteQuery(){const query=(location.hash||'').split('?')[1]||'';return new URLSearchParams(query)}
function render(resetScroll=false){const path=routePath();let view='';
 if(path==='/'||path==='')view=renderHome();else if(path==='/shop'){
  view=renderShop();
 }else if(path.startsWith('/product/'))view=renderProduct(path.split('/')[2]);else if(path==='/collections')view=renderCollections();else if(path==='/wishlist')view=renderWishlist();else if(path==='/compare')view=renderCompare();else if(path==='/account')view=renderAccount();else if(path==='/checkout')view=renderCheckout();else if(path==='/about')view=renderAbout();else if(path==='/admin')view=renderAdmin();else view=renderNotFound();
 const admin=path==='/admin';
 $('#app').innerHTML=admin?view:`${renderHeader()}${view}${renderFooter()}${state.compare.length?`<div class="compare-floating"><div>${ic('compare',18)} <b>${state.compare.length} / 3 selected</b><span>Compare favorites</span></div><a href="#/compare" class="btn btn-dark btn-small">Compare now ${ic('arrow',15)}</a><button data-action="clearCompare" aria-label="Clear comparison">${ic('close',18)}</button></div>`:''}`;
 document.title=path==='/shop'?'Shop all — FORMA':path==='/admin'?'Admin Dashboard — FORMA':path.startsWith('/product/')?`${getProduct(path.split('/')[2])?.name||'Product'} — FORMA`:'FORMA — Design your everyday';
 renderOverlay();if(resetScroll)window.scrollTo({top:0,behavior:'instant'});
}
function toast(text,type='success'){const area=$('#toast-region');const el=document.createElement('div');el.className=`toast toast-${type}`;el.innerHTML=`${ic(type==='success'?'check':'info',18)} <span>${escapeHtml(text)}</span>`;area.append(el);setTimeout(()=>{el.classList.add('toast-leaving');setTimeout(()=>el.remove(),250)},3000)}
function addToCart(id,qty=1,open=true){const p=getProduct(id);if(!p)return;if(p.stock<=0)return toast('This item is out of stock.','error');const line=state.cart.find(i=>i.id===p.id);const next=(line?.quantity||0)+qty;if(next>p.stock)return toast(`Only ${p.stock} left in stock.`,'error');line?(line.quantity=next,line.variant=state.selectedVariant||line.variant):state.cart.push({id:p.id,quantity:qty,variant:state.selectedVariant||p.colors?.[0]||'Default'});persist();toast(`${p.name} added to your bag.`);if(open){state.drawer='cart';render()}else render();}
function changeCartQty(id,change){const line=state.cart.find(i=>i.id===id),p=getProduct(id);if(!line)return;if(change>0&&line.quantity>=p.stock)return toast('Maximum available stock reached.','error');line.quantity+=change;if(line.quantity<=0)state.cart=state.cart.filter(i=>i.id!==id);persist();render()}
function toggleWishlist(id){const p=getProduct(id);if(!p)return;const index=state.wishlist.indexOf(id);if(index<0){state.wishlist.push(id);toast('Added to your wishlist.')}else{state.wishlist.splice(index,1);toast('Removed from wishlist.')}persist();render()}
function toggleCompare(id){const ix=state.compare.indexOf(id);if(ix>=0){state.compare.splice(ix,1);toast('Removed from comparison.')}else if(state.compare.length>=3){toast('You can compare up to three products.','error');return}else{state.compare.push(id);toast('Added to product comparison.')}persist();render()}
function parseShopURL(){const q=parseRouteQuery();state.shop.category=categoryInfo.some(c=>c.name===q.get('category'))?q.get('category'):'All';state.shop.sort=['featured','newest','price-low','price-high','rating'].includes(q.get('sort'))?q.get('sort'):'featured';state.shop.query=(q.get('search')||'').slice(0,100);state.shop.price=650;state.shop.onlySale=false;state.shop.page=1;}
function startCheckout(){state.checkoutDone=null;location.hash='#/checkout'}
function navigate(hash){if(location.hash===hash){render(true)}else location.hash=hash}

let detailQuantity=1;
document.addEventListener('click',e=>{
 const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,id=Number(btn.dataset.id),value=btn.dataset.value;
 switch(action){
 case 'cart':state.drawer='cart';renderOverlay();break;
 case 'closeOverlay':closeOverlay();break;
 case 'mobile':state.mobileMenu=true;renderOverlay();break;
 case 'focusSearch':state.drawer='search';renderOverlay();break;
 case 'goWishlist':navigate('#/wishlist');break;
 case 'goAccount':navigate('#/account');break;
 case 'wishlist':toggleWishlist(id);break;
 case 'compare':toggleCompare(id);break;
 case 'clearCompare':state.compare=[];persist();render();break;
 case 'quick':state.quickView=id;state.drawer='quick';renderOverlay();break;
 case 'add':addToCart(id);break;
 case 'cartQty':changeCartQty(id,Number(value));break;
 case 'removeCart':state.cart=state.cart.filter(i=>i.id!==id);persist();render();toast('Item removed from your bag.');break;
 case 'category':state.shop.category=value;state.shop.page=1;render();break;
 case 'page':state.shop.page=Number(value);render();document.querySelector('.shop-top')?.scrollIntoView({behavior:'smooth'});break;
 case 'grid':state.shop.grid=Number(value);render();break;
 case 'clearFilters':state.shop={...state.shop,category:'All',query:'',price:650,onlySale:false,sort:'featured',page:1};render();break;
 case 'clearQuery':state.shop.query='';render();break;
 case 'removeSale':state.shop.onlySale=false;render();break;
 case 'toggleFilters':$('#shop-sidebar')?.classList.toggle('filters-visible');break;
 case 'popularSearch':closeOverlay();navigate('#/shop?search='+encodeURIComponent(value));break;
 case 'color':{document.querySelectorAll('.swatch').forEach(s=>s.classList.remove('active'));btn.classList.add('active');state.selectedVariant=value;const lbl=$('#color-label');if(lbl)lbl.textContent=value;const p=getProduct(Number(routePath().split('/')[2]));const variant=variantImageFor(p?.image,value);const main=$('#detail-image');if(main)main.src=asset(variant);document.querySelectorAll('.detail-thumb img').forEach(img=>img.src=asset(variant));break;}
 case 'thumb':document.querySelectorAll('.detail-thumb').forEach(s=>s.classList.remove('active'));btn.classList.add('active');const image=$('#detail-image');if(image){image.style.filter=value==='b'?'brightness(1.12) saturate(.7)':value==='c'?'brightness(.75) contrast(1.1)':'none'}break;
 case 'detailQty':detailQuantity=Math.max(1,Math.min(getProduct(Number(routePath().split('/')[2]))?.stock||1,detailQuantity+Number(value)));if($('#detail-qty'))$('#detail-qty').textContent=detailQuantity;break;
 case 'detailAdd':addToCart(id,detailQuantity);detailQuantity=1;break;
 case 'buyNow':addToCart(id,detailQuantity,false);detailQuantity=1;closeOverlay();startCheckout();break;
 case 'adminView':state.adminView=value;render(true);break;
 case 'adminLogout':state.adminAuthorized=false;sessionStorage.removeItem('forma_admin');render();break;
 case 'resetDemo':if(confirm('Reset all local demo data, including your saved cart, wishlist, orders and inventory edits?')){for(const key of ['cart','wishlist','compare','orders','products','deleted','newsletter','coupon','orderStatuses'])localStorage.removeItem('forma_'+key);state.cart=[];state.wishlist=[];state.compare=[];state.orders=[];state.productOverrides={};state.deletedProducts=[];state.newsletter=[];state.coupon='';toast('Demo data reset.');render();}break;
 case 'openProductEditor':state.editProductId=null;state.drawer='editor';renderOverlay();break;
 case 'editProduct':state.editProductId=id;state.drawer='editor';renderOverlay();break;
 case 'deleteProduct':{const p=getProduct(id);if(!p)return;if(confirm(`Hide "${p.name}" from the storefront? You can reset demo data to restore it.`)){state.deletedProducts.push(id);persist();toast('Product hidden from storefront.');render()}break;}
 }
});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.id==='shop-sort'){state.shop.sort=el.value;state.shop.page=1;render()}
 if(el.id==='sale-only'){state.shop.onlySale=el.checked;state.shop.page=1;render()}
 if(el.dataset.order){const statuses=readStore('orderStatuses',{});statuses[el.dataset.order]=el.value;saveStore('orderStatuses',statuses);toast('Order status updated.');}
});
document.addEventListener('input',e=>{
 if(e.target.id==='price-slider'){state.shop.price=Number(e.target.value);if($('#price-range-value'))$('#price-range-value').textContent=money(state.shop.price)+(state.shop.price===650?'+':'');clearTimeout(window._priceTimer);window._priceTimer=setTimeout(()=>render(),170)}
});
document.addEventListener('submit',e=>{
 const f=e.target;const data=new FormData(f);
 if(f.id==='newsletter-form'){e.preventDefault();const email=String(data.get('email')||'').trim();if(!email)return;state.newsletter=Array.from(new Set([...state.newsletter,email]));persist();f.reset();toast('You’re on the good list. (Demo subscription)')}
 if(f.id==='coupon-form'){e.preventDefault();const code=String(data.get('coupon')||'').trim().toUpperCase();if(code==='FORM10'){state.coupon=code;persist();toast('Discount applied — 10% off.');render()}else if(!code){state.coupon='';persist();render()}else toast('Invalid code. Try FORM10.','error')}
 if(f.id==='checkout-form'){e.preventDefault();if(!f.reportValidity())return;const order={id:'FM-'+String(Date.now()).slice(-8),date:new Date().toISOString(),status:'Placed',items:state.cart.map(i=>{const p=getProduct(i.id);return {id:i.id,name:p?.name||'Product',price:p?.price||0,quantity:i.quantity,variant:i.variant}}),subtotal:cartSubtotal(),discount:discount(),shipping:cartShipping(),total:cartTotal(),customer:{firstName:String(data.get('firstName')),lastName:String(data.get('lastName')),email:String(data.get('email')),city:String(data.get('city')),country:String(data.get('country'))}};state.orders.push(order);state.checkoutDone=order;state.cart=[];state.coupon='';persist();render(true)}
 if(f.id==='admin-login'){e.preventDefault();if(String(data.get('email')).toLowerCase().trim()==='admin@forma.demo'&&String(data.get('password'))==='demo1234'){state.adminAuthorized=true;sessionStorage.setItem('forma_admin','yes');toast('Welcome to the admin demo.');render(true)}else{const error=$('#login-error');if(error)error.textContent='Incorrect demo credentials. Please try again.'}}
 if(f.id==='editor-form'){e.preventDefault();const original=getProduct(state.editProductId);const obj={...original,id:original?.id||Date.now(),name:String(data.get('name')).trim().slice(0,100),category:String(data.get('category')),image:String(data.get('image')),price:Number(data.get('price')),stock:Number(data.get('stock')),detail:String(data.get('detail')).trim().slice(0,400),badge:String(data.get('badge')||'').trim().slice(0,25),tag:original?.tag||'Beautifully useful, quietly intentional.',rating:original?.rating||4.8,reviews:original?.reviews||0,colors:original?.colors||['Natural'],specs:original?.specs||['Thoughtful design','Made for daily life']};if(!obj.name||obj.price<1||obj.stock<0)return;state.productOverrides[obj.id]=obj;persist();closeOverlay();render();toast(original?'Product updated.':'New product added.')}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape')closeOverlay();
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.drawer='search';renderOverlay()}
 if(e.key==='Enter'&&e.target.id==='global-search'){e.preventDefault();const query=e.target.value.trim();closeOverlay();navigate('#/shop?search='+encodeURIComponent(query))}
});
window.addEventListener('hashchange',()=>{const path=routePath();if(path==='/shop')parseShopURL();closeOverlay();detailQuantity=1;state.selectedVariant=null;if(path!=='/checkout')state.checkoutDone=null;render(true);if(location.hash==='#/about#faq')setTimeout(()=>$('#faq')?.scrollIntoView(),100)});
// Cleanup inventory conflicts after a locally simulated stock edit / deletion.
state.cart=state.cart.filter(i=>getProduct(i.id));persist();
if(routePath()==='/shop')parseShopURL();
render();
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
